await test("网络抖动：首轮整体失败、重试返回 MEMBER_NOT_FOUND，不回滚不复活", async () => {
  let round = 0;
  const rt = createWorkspaceRuntime({ members: [{ id: "a" }, { id: "b" }, { id: "c" }], transport: { send: async (batch) => {
    round += 1;
    if (round === 1) throw new Error("timeout");
    return { appliedSeq: 20, idempotent: batch.map((m) => ({ mutationId: m.id, code: "MEMBER_NOT_FOUND" })) };
  } } });
  const first = await rt.deleteMembers(["a", "b"]);
  assert.equal(first.error.code, "QUEUE_BATCH_FAILED");
  assert.equal(rt.vault.getMember("a").pendingAction, "delete");
  assert.equal(rt.vault.getMember("a").lastError, null);
  const r = await rt.flushPendingMutations();
  assert.equal(r.failed.length, 0);
  assert.equal(rt.vault.hasMember("a"), false);
  assert.equal(rt.vault.hasMember("b"), false);
  assert.equal(rt.vault.hasMember("c"), true);
});

await test("删除审批转交成员：角色移除，转交链重接后继/无后继解除，剩余成员可解析审批人", async () => {
  const rt = createWorkspaceRuntime({
    members: [{ id: "a" }, { id: "b" }, { id: "c" }, { id: "d" }],
    policy: { roleByMemberId: { a: "member", b: "approver", c: "admin", d: "member" }, delegateByMemberId: { a: "b", b: "c", d: "b" } },
    transport: { send: applyAll(4) },
  });
  await rt.deleteMembers("b");
  assert.equal(rt.policyRoleIndex.getRole("b"), null);
  assert.equal(rt.policyRoleIndex.hasRole("b"), false);
  assert.ok(rt.policyRoleIndex.listDelegations().every((d) => d.memberId !== "b" && d.delegateId !== "b"));
  assert.equal(rt.policyRoleIndex.resolveApproverId("a"), "c");
  assert.equal(rt.policyRoleIndex.resolveApproverId("d"), "c");
  await rt.deleteMembers("c");
  assert.deepEqual(rt.policyRoleIndex.listDelegations(), []);
  assert.equal(rt.policyRoleIndex.resolveApproverId("a"), "a");
  const r = await rt.assignRole("b", "admin");
  assert.equal(r.error.code, "MEMBER_NOT_FOUND");
  assert.equal(rt.policyRoleIndex.hasRole("b"), false);
});

await test("服务器删除事件与快照缺席共用同一 finalize 清理角色索引", async () => {
  const rt = createWorkspaceRuntime({
    members: [{ id: "a" }, { id: "b" }, { id: "c" }],
    policy: { roleByMemberId: { a: "member", b: "approver", c: "admin" }, delegateByMemberId: { a: "b", b: "c" } },
    transport: { send: applyAll(1) },
  });
  rt.stream.applyDelta({ seq: 5, events: [{ type: "member.removed", memberId: "b" }] });
  assert.equal(rt.vault.hasMember("b"), false);
  assert.equal(rt.policyRoleIndex.hasRole("b"), false);
  assert.equal(rt.policyRoleIndex.resolveApproverId("a"), "c");
  rt.stream.applyServerSnapshot({ snapshotSeq: 4, members: [{ id: "a" }, { id: "b" }, { id: "c" }] });
  assert.equal(rt.vault.hasMember("b"), false);
  const res = rt.stream.applyServerSnapshot({ snapshotSeq: 6, members: [{ id: "a" }] });
  assert.deepEqual(res.removed, ["c"]);
  assert.equal(rt.policyRoleIndex.hasRole("c"), false);
  assert.deepEqual(rt.policyRoleIndex.listDelegations(), []);
  assert.equal(rt.policyRoleIndex.resolveApproverId("a"), "a");
});

await test("删除失败回滚后成员与角色仍完整，且后续可再次删除", async () => {
  let round = 0;
  const rt = createWorkspaceRuntime({ members: [{ id: "a" }], policy: { roleByMemberId: { a: "approver" } }, transport: { send: async (b) => {
    round += 1;
    return round === 1 ? { appliedSeq: 1, failed: [{ mutationId: b[0].id, code: "FORBIDDEN", message: "无权限" }] } : { appliedSeq: 2, applied: b.map((m) => m.id) };
  } } });
  await rt.deleteMembers("a");
  assert.equal(rt.vault.getMember("a").lastError, "无权限");
  assert.equal(rt.vault.getMember("a").pendingAction, null);
  assert.equal(rt.policyRoleIndex.getRole("a"), "approver");
  await rt.flushPendingMutations();
  assert.equal(rt.vault.hasMember("a"), false);
  assert.equal(rt.policyRoleIndex.hasRole("a"), false);
});

await test("角色分配：失败回滚到已确认角色，重试成功后本地与服务器一致", async () => {
  let round = 0;
  const rt = createWorkspaceRuntime({ members: [{ id: "c" }], policy: { roleByMemberId: { c: "member" } }, transport: { send: async (b) => (++round === 1 ? { appliedSeq: 1, failed: [{ mutationId: b[0].id, code: "TEMP" }] } : { appliedSeq: 2, applied: b.map((m) => m.id) }) } });
  await rt.assignRole("c", "admin");
  assert.equal(rt.policyRoleIndex.getRole("c"), "member");
  assert.equal(rt.queue.size, 1);
  await rt.flushPendingMutations();
  assert.equal(rt.policyRoleIndex.getRole("c"), "admin");
});

await test("角色分配：旧意图失败不覆盖在途期间的新意图", async () => {
  const gate = deferred();
  let round = 0;
  const rt = createWorkspaceRuntime({ members: [{ id: "c" }], policy: { roleByMemberId: { c: "member" } }, transport: { send: async (b) => {
    round += 1;
    if (round === 1) { await gate.promise; return { appliedSeq: 1, failed: b.map((m) => ({ mutationId: m.id, code: "TEMP" })) }; }
    return { appliedSeq: 2, applied: b.map((m) => m.id) };
  } } });
  const p = rt.assignRole("c", "admin");
  const q = rt.assignRole("c", "manager");
  gate.resolve();
  await Promise.all([p, q]);
  assert.equal(rt.policyRoleIndex.getRole("c"), "manager");
  assert.deepEqual(rt.queue.listPending().map((m) => m.kind), ["assignWorkspaceMemberRole", "assignWorkspaceMemberRole"]);
  await rt.flushPendingMutations();
  assert.equal(rt.policyRoleIndex.getRole("c"), "manager");
  assert.equal(rt.queue.size, 0);
});

await test("重复删除同一成员只保留一条删除意图（离线连续删除、在途再次删除）", async () => {
  let offline = true;
  const sent = [];
  const rt = createWorkspaceRuntime({ members: [{ id: "a" }, { id: "b" }], isOffline: () => offline, transport: { send: async (b) => { sent.push(b.map((m) => m.memberIds.join(","))); return { appliedSeq: 1, applied: b.map((m) => m.id) }; } } });
  await rt.deleteMembers("a");
  const again = await rt.deleteMembers(["a", "b"]);
  assert.deepEqual(again.queued, ["b"]);
  assert.deepEqual(rt.queue.listPending().map((m) => m.memberIds.join(",")), ["a", "b"]);
  offline = false;
  await rt.flushPendingMutations();
  assert.deepEqual(sent, [["a", "b"]]);
