await test("服务器把 MEMBER_NOT_FOUND 放在 failed 列表中也按幂等成功处理；异常结果条目不导致丢操作", async () => {
  const rt = createWorkspaceRuntime({ members: [{ id: "a" }, { id: "b" }], transport: { send: async (b) => ({ appliedSeq: 3, applied: [], idempotent: [null], failed: [null, { mutationId: b[0].id, code: "MEMBER_NOT_FOUND" }] }) } });
  const r = await rt.deleteMembers("a");
