});

await test("服务器返回非法 appliedSeq（负数）时删除仍落库并留下保守墓碑", async () => {
  const rt = createWorkspaceRuntime({ members: [{ id: "a" }, { id: "b" }], policy: { roleByMemberId: { a: "member", b: "member" } }, transport: { send: async (b) => ({ appliedSeq: -1, applied: b.map((m) => m.id) }) } });
  await rt.deleteMembers("a");
  assert.equal(rt.vault.hasMember("a"), false);
  assert.deepEqual(rt.vault.tombstoneOf("a"), { seq: null });
  assert.equal(rt.policyRoleIndex.hasRole("a"), false);
  rt.stream.applyServerSnapshot({ snapshotSeq: 100, members: [{ id: "a" }, { id: "b", displayName: "B" }] });
