## 6. 随机时序压力测试（不变式）

在随机交错的离线/在线切换、删除、角色分配、flush、新旧快照、增量，以及随机的传输结果（整体失败、部分失败、`MEMBER_NOT_FOUND`、成功）下，检查 5 条不变式：

1. 所有入队的操作要么已成功结算，要么仍在队列中，不会丢失；
2. 有墓碑的成员不在库中，不在角色索引中，也不出现在任何转交里；
3. 剩余成员解析审批人时不会出现悬空，也不会解析到已删除成员；
4. 服务器已删除的成员在本地不存在；
5. 队列清空后，没有成员停在“待删除”。

```bash
awk '/^```js fuzz$/{f=1;next} /^```$/{f=0} f' DESIGN.md > /tmp/fuzz.mjs && for s in 1 7 42; do node /tmp/fuzz.mjs . $s; done
```

```js fuzz
// 用法：node fuzz.mjs [工作区根目录] [随机种子]
// 随机时序压力测试：随机交错 删除/角色分配/离线切换/flush/快照/增量/传输结果，检查不变式
import { pathToFileURL } from "node:url";
import path from "node:path";
const root = pathToFileURL(path.resolve(process.argv[2] ?? ".") + "/").href;
const { createWorkspaceRuntime } = await import(root + "src/actions/WorkspaceMemberActions.js");
let seed = Number(process.argv[3] ?? 1);
const rnd = () => { seed = (seed * 1103515245 + 12345) & 0x7fffffff; return seed / 0x7fffffff; };
const pick = (a) => a[Math.floor(rnd() * a.length)];
const ROLES = ["owner", "admin", "approver", "manager", "member"];
let violations = 0;
for (let run = 0; run < 400; run++) {
  const ids = ["m1", "m2", "m3", "m4", "m5"];
  const roleByMemberId = Object.fromEntries(ids.map((id) => [id, pick(ROLES)]));
  const delegateByMemberId = {};
  for (const id of ids) if (rnd() < 0.5) { const t = pick(ids); if (t !== id) delegateByMemberId[id] = t; }
  let serverSeq = 10;
  const server = new Map(ids.map((id) => [id, true]));
  const history = [{ seq: 10, alive: new Set(ids) }];
  const commit = () => { history.push({ seq: serverSeq, alive: new Set(ids.filter((id) => server.get(id))) }); };
  let offline = false;
  const enqueued = new Set(); const settled = new Set();
  const rt = createWorkspaceRuntime({
    members: ids.map((id) => ({ id })), policy: { roleByMemberId, delegateByMemberId }, isOffline: () => offline,
    transport: { send: async (batch) => {
      await new Promise((r) => setTimeout(r, Math.floor(rnd() * 3)));
      const mode = rnd();
      if (mode < 0.15) throw new Error("net");
      const applied = [], failed = [], idempotent = [];
      serverSeq += 1;
      for (const m of batch) {
        const r = rnd();
        if (m.kind === "deleteWorkspaceMember") {
          if (m.memberIds.every((id) => !server.get(id)) || (r < 0.2)) { for (const id of m.memberIds) server.set(id, false); idempotent.push({ mutationId: m.id, code: "MEMBER_NOT_FOUND" }); }
          else if (r < 0.4) failed.push({ mutationId: m.id, code: "TEMP", message: "t" });
          else { for (const id of m.memberIds) server.set(id, false); applied.push(m.id); }
        } else {
          if (r < 0.3) failed.push({ mutationId: m.id, code: "TEMP" }); else applied.push(m.id);
        }
      }
      commit();
      return { appliedSeq: serverSeq, applied, failed, idempotent };
    } },
  });
  rt.queue.subscribe((e) => { if (e.type === "mutation.succeeded") settled.add(e.mutation.id); });
  const origEnqueue = rt.queue.enqueue.bind(rt.queue);
  rt.queue.enqueue = (m) => { enqueued.add(m.id); return origEnqueue(m); };
  const ops = [];
  for (let step = 0; step < 30; step++) {
    const r = rnd();
    try {
      if (r < 0.25) ops.push(rt.deleteMembers(rnd() < 0.5 ? pick(ids) : [pick(ids), pick(ids)]));
      else if (r < 0.45) ops.push(rt.assignRole(pick(ids), pick(ROLES)));
      else if (r < 0.55) offline = !offline;
      else if (r < 0.7) ops.push(rt.flushPendingMutations());
      else if (r < 0.8) { const h = history[Math.max(0, history.length - 1 - Math.floor(rnd() * 4))]; rt.stream.applyServerSnapshot({ snapshotSeq: h.seq, members: [...h.alive].map((id) => ({ id, displayName: id + "-s" + h.seq })) }); }
      else if (r < 0.9) { const alive = ids.filter((id) => server.get(id)); if (alive.length) { serverSeq += 1; commit(); rt.stream.applyDelta({ seq: serverSeq, events: [{ type: "member.updated", member: { id: pick(alive), displayName: "d" } }] }); } }
      else await new Promise((res) => setTimeout(res, 2));
    } catch (e) { if (!["ROLE_INDEX_ROLE_INVALID"].includes(e.code)) { console.log("异常", run, e); violations++; } }
  }
  offline = false;
  await Promise.allSettled(ops);
  for (let i = 0; i < 40 && rt.queue.size > 0; i++) await rt.flushPendingMutations();
  const check = (cond, msg) => { if (!cond) { violations++; if (violations < 10) console.log("违反", run, msg); } };
  // 不变式 1：没有操作丢失
  for (const id of enqueued) check(settled.has(id) || rt.queue.listPending().some((m) => m.id === id), "操作丢失 " + id);
  // 不变式 2：已删除成员不在角色索引/转交链
  for (const t of (typeof rt.vault.listTombstones === "function" ? rt.vault.listTombstones() : ids.filter((id) => !server.get(id) && !rt.vault.hasMember(id)).map((id) => ({ id })))) {
    check(!rt.vault.hasMember(t.id), "墓碑成员仍在库 " + t.id);
    check(!rt.policyRoleIndex.hasRole(t.id), "已删成员仍有角色 " + t.id);
    check(rt.policyRoleIndex.listDelegations().every((d) => d.memberId !== t.id && d.delegateId !== t.id), "转交指向已删成员 " + t.id);
  }
  // 不变式 3：剩余有角色成员解析审批人不出现悬空
  for (const { memberId } of rt.policyRoleIndex.listRoles()) {
    try { const a = rt.policyRoleIndex.resolveApproverId(memberId); check(!(typeof rt.vault.isDeleted === "function" ? rt.vault.isDeleted(a) : !rt.vault.hasMember(a)), "解析到已删成员"); }
    catch (e) { check(e.code === "ROLE_INDEX_DELEGATION_CYCLE", "解析异常 " + e.code); }
  }
  // 不变式 4：服务器已删除的成员（所有删除都结算后）不在本地
  for (const id of ids) if (!server.get(id)) check(!rt.vault.hasMember(id), "服务器已删但本地仍在 " + id);
  // 不变式 5：队列清空后无挂起的待删除标记
  if (rt.queue.size === 0) for (const m of rt.vault.listMembers()) check(m.pendingAction === null, "队列空但仍待删除 " + m.id);
}
console.log("violations =", violations);
process.exitCode = violations ? 1 : 0;
```

