      sent.push(batch.map((m) => m.kind + ":" + m.memberIds.join(",")));
      round += 1;
      if (round === 1) { await gate.promise; return { appliedSeq: 3, applied: [batch[0].id], failed: [{ mutationId: batch[1].id, code: "MEMBER_LOCKED", message: "成员被锁定" }] }; }
      return { appliedSeq: 4, applied: batch.map((m) => m.id) };
    } },
  });
  await rt.deleteMembers("a");
  await rt.deleteMembers("b");
  offline = false;
  const p = rt.flushPendingMutations();
  assert.equal(rt.queue.isFlushing, true);
  const roleOp = rt.assignRole("c", "admin"); // 在途期间入队
  assert.equal(rt.policyRoleIndex.getRole("c"), "admin");
  gate.resolve();
  const report = await p;
  await roleOp;
  assert.deepEqual(report.succeeded.map((o) => o.mutation.memberIds[0]), ["a"]);
  assert.deepEqual(report.failed.map((o) => [o.mutation.memberIds[0], o.error.code]), [["b", "MEMBER_LOCKED"]]);
  assert.equal(rt.vault.hasMember("a"), false);
  assert.equal(rt.vault.getMember("b").pendingAction, null);
  assert.equal(rt.vault.getMember("b").lastError, "成员被锁定");
  assert.deepEqual(rt.queue.listPending().map((m) => m.kind + ":" + m.memberIds.join(",")), ["deleteWorkspaceMember:b", "assignWorkspaceMemberRole:c"]);
  const second = await rt.flushPendingMutations();
  assert.deepEqual(sent[1], ["deleteWorkspaceMember:b", "assignWorkspaceMemberRole:c"]);
  assert.equal(second.failed.length, 0);
  assert.equal(rt.queue.size, 0);
  assert.equal(rt.vault.hasMember("b"), false);
  assert.equal(rt.policyRoleIndex.getRole("c"), "admin");
});

