// src/components/AttachmentPreviewModal.js — 底层父模态屏（内嵌二级确认弹窗）
import * as ModalStack from "../libs/ModalStack.js";
import * as Navigation from "../libs/Navigation.js";

export function createAttachmentPreviewModal() {
  let isConfirmDeleteOpen = false;
  let isPreviewVisible = true;

  // 父模态框注册关闭句柄
  const unregisterParent = ModalStack.registerModalClose(() => {
    isPreviewVisible = false;
    ModalStack.onModalDidClose({ modalId: "attachment-preview" });
  }, { modalId: "attachment-preview", detachedOverlay: false });

  // 当打开二级删除确认框时，注册第二个阻塞模态框句柄
  let unregisterConfirm = null;
  function openDeleteConfirmDialog() {
    isConfirmDeleteOpen = true;
    unregisterConfirm = ModalStack.registerModalClose((isNavigating) => {
      isConfirmDeleteOpen = false;
      // 如果仅关闭确认弹窗而不等待父预览弹窗隐藏，onModalDidClose 就会提前触发
      ModalStack.onModalDidClose({ modalId: "delete-confirm" });
      if (!isNavigating) {
        Navigation.dismissModal();
      }
    }, { modalId: "delete-confirm", detachedOverlay: false });
  }

  return {
    openDeleteConfirmDialog,
    getState: () => ({ isPreviewVisible, isConfirmDeleteOpen }),
    dispose: () => {
      unregisterConfirm?.();
      unregisterParent();
    },
  };
}

// src/components/BaseModal.js
import * as ModalStack from "../libs/ModalStack.js";
import * as Navigation from "../libs/Navigation.js";

export function mountBaseModal({ modalId, detachedOverlay = false, onHide }) {
  let visible = true;
  let lastTxId = undefined;

  const unregister = ModalStack.registerModalClose((isNavigating, txId) => {
    visible = false;
    lastTxId = txId;
    if (!detachedOverlay) {
      Navigation.setTransitionLock(true);
    }
    queueMicrotask(() => {
      if (!detachedOverlay) {
        Navigation.setTransitionLock(false);
      }
      onHide?.(isNavigating, lastTxId);
      ModalStack.onModalDidClose({ modalId, detachedOverlay, txId: lastTxId });
    });
  }, { modalId, detachedOverlay });

  return {
    isVisible: () => visible,
    dispose: () => unregister(),
  };
}

// src/libs/ModalStack.js
import { notifyOverlayObservers } from "./OverlayBus.js";

const closeModals = [];
let onModalClose = null;
let isNavigatingFlag = false;
let activeTransactionId = 0;

export function registerModalClose(closeHandler, options = {}) {
  const entry = {
    closeHandler,
    detachedOverlay: Boolean(options.detachedOverlay),
    modalId: options.modalId ?? "anonymous-modal",
  };
  closeModals.push(entry);
  return () => {
    const idx = closeModals.indexOf(entry);
    if (idx !== -1) closeModals.splice(idx, 1);
  };
}

export function close(onModalCloseCallback, isNavigating = true) {
  const txId = ++activeTransactionId;
  const blockingModals = closeModals.filter((m) => !m.detachedOverlay);
  if (blockingModals.length === 0) {
    if (typeof onModalCloseCallback === "function") onModalCloseCallback();
    return txId;
  }
  onModalClose = onModalCloseCallback;
  isNavigatingFlag = Boolean(isNavigating);
  for (let i = blockingModals.length - 1; i >= 0; i--) {
    blockingModals[i].closeHandler(isNavigatingFlag, txId);
  }
  return txId;
}

export function onModalDidClose(options = {}) {
  if (options.detachedOverlay) {
    notifyOverlayObservers("detached-closed", options.modalId);
    return;
  }
  if (options.txId !== undefined && options.txId !== activeTransactionId) {
    // 过期事务的延迟隐藏事件，不得触发当前轮次的 onModalClose
    return;
  }
  if (!onModalClose) {
    return;
  }
  const cb = onModalClose;
  onModalClose = null;
  isNavigatingFlag = false;
  cb();
}

export function getRegisteredEntries() {
  return [...closeModals];
}

// src/libs/Navigation.js
import * as ModalStack from "./ModalStack.js";

const routeStack = [{ name: "WorkspaceHome", isModalScreen: false }];
let transitionLocked = false;

export function setTransitionLock(locked) {
  transitionLocked = Boolean(locked);
}

export function navigate(route, options = {}) {
  if (transitionLocked) {
    throw new Error("NAVIGATION_LOCKED_DURING_MODAL_ANIMATION");
  }
  routeStack.push({
    name: route,
    isModalScreen: Boolean(options.isModalScreen),
  });
}

export function dismissModal() {
  if (routeStack.length > 1) {
    routeStack.pop();
  }
}

export function openQuickSwitcherShortcut() {
  ModalStack.close(() => {
    navigate("/quick-switcher", { isModalScreen: true });
  }, true);
}

export function getRouteStack() {
  return [...routeStack];
}

// src/libs/OverlayBus.js
import { registerModalClose, onModalDidClose } from "./ModalStack.js";

const listeners = new Set();

export function notifyOverlayObservers(event, modalId) {
  for (const fn of listeners) fn(event, modalId);
}

/**
 * 挂载全局非阻塞状态浮层（如离线提示条、复制成功 Toast）。
 * 该浮层常驻在 closeModals 列表中，且带有 detachedOverlay: true 标记。
 * 如果任何方案直接使用 closeModals.length 作为阻塞模态框总数（而不排除 detachedOverlay），
 * 会因为常驻 Toast 从不关闭而导致计数永远无法归零、导航回调永久死锁！
 */
export function mountPersistentToastOverlay() {
  return registerModalClose(
    () => {
      onModalDidClose({ modalId: "persistent-toast", detachedOverlay: true });
    },
    { modalId: "persistent-toast", detachedOverlay: true }
  );
}

import assert from "node:assert/strict";
import { MemberVault, MemberVaultError, normalizeMember } from "./store/MemberVault.js";
import { finalizeMemberDeletion } from "./store/finalizeMemberDeletion.js";
import { PolicyRoleIndex, PolicyRoleIndexError, WORKSPACE_ROLE_IDS } from "./policy/PolicyRoleIndex.js";
import { OfflineMutationQueue, OfflineMutationQueueError, createOfflineMutationQueue } from "./queue/OfflineMutationQueue.js";
import { DeltaStream, DeltaStreamError } from "./sync/DeltaStream.js";
import { createWorkspaceMemberActions, createWorkspaceRuntime } from "./actions/WorkspaceMemberActions.js";
import { isMemberHidden, buildMemberRowViewModel, buildMemberListViewModel } from "./ui/OfflineWithFeedback.js";

let passed = 0;
async function test(name, verify) {
  await verify();
  passed += 1;
  console.log("通过 " + passed + "：" + name);
}

function deferred() {
  let resolve;
  let reject;
  const promise = new Promise((resolvePromise, rejectPromise) => {
    resolve = resolvePromise;
    reject = rejectPromise;
  });
  return { promise, resolve, reject };
}

function pendingIds(queue) { return queue.listPending().map((mutation) => mutation.id); }
function mutation(id) { return { id, kind: "验收操作", memberIds: [] }; }

await test("离线标记和视图规则不变；删除确认后旧快照逐成员过滤", async () => {
  let offline = true;
  let sends = 0;
  const runtime = createWorkspaceRuntime({
    members: [{ id: "gone" }, { id: "other", displayName: "初始" }, { id: "source" }, { id: "next" }, { id: "clock" }],
    policy: { roleByMemberId: { gone: "approver", source: "member", next: "approver" }, delegateByMemberId: { source: "gone", gone: "next" } },
    isOffline: () => offline,
    transport: { send: async (batch) => { sends += 1; return { appliedSeq: 30, applied: batch.map((item) => item.id) }; } },
  });
  const requested = await runtime.deleteMembers(["gone", "gone", "不存在", null]);
  assert.deepEqual(requested, { queued: ["gone"], flushed: false, error: null });
  assert.equal(sends, 0);
  assert.equal(await runtime.flushPendingMutations(), null);
  const row = buildMemberRowViewModel({ member: runtime.vault.getMember("gone"), isOffline: true });
  assert.equal(row.hidden, false);
  assert.equal(row.offlineIndicator, true);
  assert.equal(isMemberHidden({ pendingAction: "delete", isOffline: false }), true);
  assert.equal(buildMemberListViewModel({ members: runtime.vault.listMembers(), isOffline: false }).hiddenCount, 1);
  let deletionObservation = null;
  runtime.vault.subscribe((event) => {
    if (event.reason !== "member.removed" || event.memberId !== "gone") return;
    // 被测代码会隔离观察者异常，故只采样，必须在回调外断言。
    deletionObservation = {
      seq: runtime.vault.lastMutationSeqOf("gone"),
      hasRole: runtime.policyRoleIndex.hasRole("gone"),
      delegate: runtime.policyRoleIndex.getDelegate("source"),
    };
  });
  offline = false;
  const report = await runtime.flushPendingMutations();
  assert.equal(report.succeeded.length, 1);
  assert.equal(report.failed.length, 0);
  assert.deepEqual(deletionObservation, { seq: 30, hasRole: false, delegate: "next" });
  assert.equal(runtime.vault.hasMember("gone"), false);
  assert.equal(runtime.vault.isMemberDeleted("gone"), true);
  assert.equal(runtime.policyRoleIndex.getDelegate("gone"), null);
  assert.equal(runtime.policyRoleIndex.resolveApproverId("source"), "next");
  // 整体游标更大也不能丢弃其他成员可用的旧快照数据。
  runtime.stream.applyDelta({ seq: 100, events: [{ type: "member.updated", member: { id: "clock", displayName: "最新" } }] });
  for (const snapshotSeq of [29, 30]) {
    const result = runtime.stream.applyServerSnapshot({ snapshotSeq, members: [
      { id: "gone" }, { id: "other", displayName: "快照更新 " + snapshotSeq }, { id: "source" }, { id: "next" },
    ] });
    assert.equal(result.applied, true);
    assert.equal(runtime.vault.hasMember("gone"), false);
    assert.equal(runtime.vault.getMember("other").displayName, "快照更新 " + snapshotSeq);
    assert.equal(runtime.vault.getMember("clock").displayName, "最新");
    assert.equal(runtime.stream.cursor, 100);
  }
  await assert.rejects(runtime.assignRole("gone", "admin"), (error) => error.code === "ROLE_INDEX_UNKNOWN_MEMBER");
  assert.equal(runtime.policyRoleIndex.hasRole("gone"), false);
  assert.deepEqual(await runtime.deleteMembers("gone"), { queued: [], flushed: false, error: null });
});

await test("在册成员的新序号不会被旧快照覆盖或被缺项删除", () => {
  const vault = new MemberVault([{ id: "recent" }, { id: "other" }]);
  const stream = new DeltaStream({ vault });
  stream.applyDelta({ seq: 50, events: [{ type: "member.updated", member: { id: "recent", displayName: "更新的数据" } }] });
  stream.applyServerSnapshot({ snapshotSeq: 40, members: [{ id: "recent", displayName: "旧数据" }, { id: "other", displayName: "正常刷新" }] });
  assert.equal(vault.getMember("recent").displayName, "更新的数据");
  assert.equal(vault.getMember("other").displayName, "正常刷新");
  stream.applyServerSnapshot({ snapshotSeq: 41, members: [{ id: "other", displayName: "再次刷新" }] });
  assert.equal(vault.hasMember("recent"), true);
  assert.equal(vault.getMember("other").displayName, "再次刷新");
  const before = { members: vault.listMembers(), revision: vault.revision, cursor: stream.cursor };
  assert.throws(() => stream.applyServerSnapshot({ snapshotSeq: 60, members: [{ id: "other" }, { id: "无效", status: "未知" }] }), (error) => error.code === "MEMBER_STATUS_INVALID");
  assert.deepEqual({ members: vault.listMembers(), revision: vault.revision, cursor: stream.cursor }, before);
});

await test("墓碑有版本而非永久黑名单；缺席快照继续推进屏障", () => {
  const vault = new MemberVault([{ id: "a" }, { id: "b" }]);
  const stream = new DeltaStream({ vault });
  finalizeMemberDeletion({ vault, memberId: "a", mutationSeq: 10 });
  stream.applyServerSnapshot({ snapshotSeq: 20, members: [{ id: "b" }] });
  assert.equal(vault.lastMutationSeqOf("a"), 20);
  stream.applyServerSnapshot({ snapshotSeq: 15, members: [{ id: "a" }, { id: "b", displayName: "不能覆盖序号二十的数据" }] });
  assert.equal(vault.hasMember("a"), false);
  stream.applyServerSnapshot({ snapshotSeq: 21, members: [{ id: "a", displayName: "重新加入" }, { id: "b" }] });
  assert.equal(vault.getMember("a").displayName, "重新加入");
  assert.equal(vault.isMemberDeleted("a"), false);
  stream.applyDelta({ seq: 22, events: [{ type: "member.removed", memberId: "a" }] });
  stream.applyDelta({ seq: 23, events: [{ type: "member.added", member: { id: "a", displayName: "增量重新加入" } }] });
  assert.equal(vault.getMember("a").displayName, "增量重新加入");
});

await test("丢失成功回包后重试 MEMBER_NOT_FOUND 只发成功事件且不回滚", async () => {
  let offline = true;
  let attempt = 0;
  const serverMembers = new Set(["a"]);
  const runtime = createWorkspaceRuntime({
    members: [{ id: "a" }], policy: { roleByMemberId: { a: "admin" } }, isOffline: () => offline,
    transport: { send: async (batch) => {
      attempt += 1;
      if (attempt === 1) { serverMembers.delete("a"); throw new Error("成功回包丢失"); }
      assert.equal(serverMembers.has("a"), false);
      assert.deepEqual(batch[0].successData, [{ code: "MEMBER_NOT_FOUND", behavior: "treatAsApplied" }]);
      return { appliedSeq: 59, idempotent: [{ mutationId: batch[0].id, code: "MEMBER_NOT_FOUND", appliedSeq: 60 }] };
    } },
  });
  await runtime.deleteMembers("a");
  const originalId = pendingIds(runtime.queue)[0];
  offline = false;
  const first = await runtime.flushPendingMutations();
  assert.equal(first.error.code, "QUEUE_BATCH_FAILED");
  assert.equal(first.failed.length, 1);
  assert.deepEqual(pendingIds(runtime.queue), [originalId]);
  const events = [];
  const vaultEvents = [];
  runtime.queue.subscribe((event) => events.push(event.type));
  runtime.vault.subscribe((event) => vaultEvents.push(event.reason));
  const second = await runtime.flushPendingMutations();
  assert.deepEqual(events, ["mutation.succeeded"]);
  assert.equal(vaultEvents.includes("member.restored"), false);
  assert.equal(second.succeeded[0].result.outcome, "idempotent");
  assert.equal(second.succeeded[0].result.code, "MEMBER_NOT_FOUND");
  assert.equal(second.failed.length, 0);
  assert.equal(runtime.queue.size, 0);
  assert.equal(runtime.vault.hasMember("a"), false);
  assert.equal(runtime.policyRoleIndex.hasRole("a"), false);
  assert.equal(runtime.vault.lastMutationSeqOf("a"), 60);
  runtime.stream.applyServerSnapshot({ snapshotSeq: 59, members: [{ id: "a" }] });
  assert.equal(runtime.vault.hasMember("a"), false);
});

await test("failed 分组的 MEMBER_NOT_FOUND 也幂等成功；无序号删除保守保护", async () => {
  let offline = true;
  const runtime = createWorkspaceRuntime({
    members: [{ id: "a" }, { id: "b" }], isOffline: () => offline,
    transport: { send: async (batch) => ({ appliedSeq: -1, failed: [{ mutationId: batch[0].id, code: "MEMBER_NOT_FOUND" }] }) },
  });
  await runtime.deleteMembers("a");
  offline = false;
  const events = [];
  runtime.queue.subscribe((event) => events.push(event.type));
  const result = await runtime.flushPendingMutations();
  assert.deepEqual(events, ["mutation.succeeded"]);
  assert.equal(result.failed.length, 0);
  assert.equal(result.succeeded[0].result.appliedSeq, null);
  runtime.stream.applyServerSnapshot({ snapshotSeq: 100, members: [{ id: "a" }, { id: "b", displayName: "其他成员仍更新" }] });
  assert.equal(runtime.vault.hasMember("a"), false);
  assert.equal(runtime.vault.getMember("b").displayName, "其他成员仍更新");
  runtime.stream.applyDelta({ seq: 101, events: [{ type: "member.removed", memberId: "a" }] });
  runtime.stream.applyDelta({ seq: 102, events: [{ type: "member.added", member: { id: "a" } }] });
  assert.equal(runtime.vault.hasMember("a"), true);
});

await test("未声明的幂等码或其他错误仍失败，不能全局吞掉错误", async () => {
  const queue = new OfflineMutationQueue({ transport: { send: async (batch) => ({
    idempotent: [{ mutationId: batch[0].id, code: "MEMBER_NOT_FOUND" }, { mutationId: batch[1].id, code: "PERMISSION_DENIED" }],
  }) } });
  queue.enqueue(mutation("无声明"));
  queue.enqueue({ ...mutation("有声明"), successData: [{ code: "MEMBER_NOT_FOUND", behavior: "treatAsApplied" }] });
  const result = await queue.flush();
  assert.equal(result.succeeded.length, 0);
  assert.deepEqual(result.failed.map((entry) => entry.error.code), ["MEMBER_NOT_FOUND", "PERMISSION_DENIED"]);
  assert.deepEqual(pendingIds(queue), ["无声明", "有声明"]);
});

await test("部分成功、失败和缺结果精确结算；保留批次后队尾及在途与回调新增操作", async () => {
  let offline = true;
  const gate = deferred();
  const sent = [];
  const serverMembers = new Set(["a", "b", "c", "d", "e"]);
  const serverRoles = new Map([["c", "member"], ["d", "member"]]);
  const runtime = createWorkspaceRuntime({
    members: [...serverMembers].map((id) => ({ id })),
    policy: { roleByMemberId: { a: "approver", b: "approver", c: "member", d: "member", e: "member" } },
    isOffline: () => offline, batchSize: 3,
    transport: { send: (batch) => {
      sent.push(batch.map((entry) => entry.id));
      if (sent.length === 1) return gate.promise;
      for (const entry of batch) {
        if (entry.kind === "deleteWorkspaceMember") for (const id of entry.memberIds) serverMembers.delete(id);
        if (entry.kind === "assignWorkspaceMemberRole") serverRoles.set(entry.memberIds[0], entry.payload.roleId);
      }
      return Promise.resolve({ appliedSeq: 10 + sent.length, applied: batch.map((entry) => entry.id) });
    } },
  });
  await runtime.deleteMembers("a");
  await runtime.deleteMembers("b");
  await runtime.deleteMembers("e");
  await runtime.assignRole("d", "admin");
  const [a, b, e, tail] = pendingIds(runtime.queue);
  offline = false;
  const flushing = runtime.queue.flush();
  assert.strictEqual(runtime.queue.flush(), flushing);
  assert.equal(runtime.queue.isFlushing, true);
  assert.throws(() => runtime.queue.enqueue({ id: a, kind: "重复" }), (error) => error.code === "QUEUE_DUPLICATE_MUTATION");
  const newRoleRequest = runtime.assignRole("c", "manager");
  const newRole = pendingIds(runtime.queue)[1];
  let rollbackObservation = "尚未收到失败";
  runtime.queue.subscribe((event) => {
    if (event.type === "mutation.failed" && event.mutation.id === b) {
      rollbackObservation = runtime.vault.getMember("b").pendingAction;
      runtime.queue.enqueue(mutation("回滚回调新增"));
    }
  });
  runtime.stream.applyServerSnapshot({ snapshotSeq: 5, members: [...serverMembers].map((id) => ({ id, displayName: "在途刷新 " + id })) });
  assert.equal(runtime.vault.getMember("b").pendingAction, "delete");
  serverMembers.delete("a");
  gate.resolve({ appliedSeq: 10, applied: [a], failed: [{ mutationId: b, code: "PERMISSION_DENIED", message: "拒绝删除" }] });
  const report = await flushing;
  await newRoleRequest;
  assert.equal(rollbackObservation, null);
  assert.deepEqual(report.succeeded.map((entry) => entry.mutation.id), [a]);
  assert.deepEqual(report.failed.map((entry) => [entry.mutation.id, entry.error.code]), [[b, "PERMISSION_DENIED"], [e, "QUEUE_RESULT_MISSING"]]);
  assert.equal(runtime.vault.hasMember("a"), false);
  assert.equal(runtime.vault.getMember("b").displayName, "在途刷新 b");
  assert.equal(runtime.vault.getMember("b").pendingAction, null);
  assert.equal(runtime.vault.getMember("b").lastError, "拒绝删除");
  assert.equal(runtime.vault.getMember("e").pendingAction, null);
  assert.equal(runtime.policyRoleIndex.getRole("c"), "manager");
  assert.deepEqual(pendingIds(runtime.queue), [b, e, tail, newRole, "回滚回调新增"]);
  await runtime.flushPendingMutations();
  assert.deepEqual(sent[1], [b, e, tail]);
  assert.deepEqual(pendingIds(runtime.queue), [newRole, "回滚回调新增"]);
  await runtime.flushPendingMutations();
  assert.deepEqual(sent[2], [newRole, "回滚回调新增"]);
  assert.equal(runtime.queue.size, 0);
  assert.equal(serverRoles.get("c"), "manager");
  assert.equal(serverRoles.get("d"), "admin");
  assert.equal(serverMembers.has("b"), false);
  assert.equal(serverMembers.has("e"), false);
});

