await test("固定种子状态机对照角色乐观层、在途新增和原序重试", async () => {
  let seed = 20260206;
  const random = (limit) => { seed = (Math.imul(seed, 1664525) + 1013904223) >>> 0; return seed % limit; };
  const roles = ["admin", "approver", "manager", "member", "owner"];
  for (let trial = 0; trial < 24; trial += 1) {
    let gate;
    let batch;
    let sequence = 0;
    let serverRole = "member";
    let confirmedRole = "member";
    const layers = new Map();
    const runtime = createWorkspaceRuntime({
      members: [{ id: "a" }], policy: { roleByMemberId: { a: "member" } }, isOffline: () => true, batchSize: 2,
      transport: { send: (sent) => { batch = [...sent]; gate = deferred(); return gate.promise; } },
    });
    const enqueueRole = async () => {
      const role = roles[random(roles.length)];
      await runtime.assignRole("a", role);
      const id = pendingIds(runtime.queue).at(-1);
      layers.set(id, { role, optimistic: true });
    };
    const expectedRole = () => {
      let role = confirmedRole;
      for (const layer of layers.values()) if (layer.optimistic) role = layer.role;
      return role;
    };
    const settle = async (flight, allApplied) => {
      const tail = pendingIds(runtime.queue);
      const result = { appliedSeq: ++sequence, applied: [], failed: [] };
      const retryIds = [];
      for (const item of batch) {
        const status = allApplied ? 0 : random(3);
        if (status === 0) {
          result.applied.push(item.id);
          confirmedRole = serverRole = item.payload.roleId;
          layers.delete(item.id);
        } else {
          if (status === 1) result.failed.push({ mutationId: item.id, code: "DENIED" });
          layers.get(item.id).optimistic = false;
          retryIds.push(item.id);
        }
      }
      gate.resolve(result);
      await flight;
      assert.deepEqual(pendingIds(runtime.queue), [...retryIds, ...tail]);
      assert.equal(runtime.policyRoleIndex.getRole("a"), expectedRole());
    };
    for (let step = 0; step < 8; step += 1) {
      await enqueueRole();
      const flight = runtime.queue.flush();
      for (let added = random(3); added > 0; added -= 1) await enqueueRole();
      await settle(flight, false);
    }
    while (runtime.queue.size > 0) await settle(runtime.queue.flush(), true);
    assert.equal(runtime.policyRoleIndex.getRole("a"), serverRole);
    assert.equal(layers.size, 0);
  }
});

