import { MemberVault } from "../store/MemberVault.js";
import { PolicyRoleIndex, PolicyRoleIndexError, WORKSPACE_ROLE_IDS } from "../policy/PolicyRoleIndex.js";
import { OfflineMutationQueue } from "../queue/OfflineMutationQueue.js";
import { DeltaStream } from "../sync/DeltaStream.js";
import { finalizeMemberDeletion } from "../store/finalizeMemberDeletion.js";

let mutationSequence = 0;
const actionStatesByVault = new WeakMap();

function actionStateFor(vault, policyRoleIndex, queue) {
  let indexes = actionStatesByVault.get(vault);
  if (!indexes) { indexes = new WeakMap(); actionStatesByVault.set(vault, indexes); }
  let queues = indexes.get(policyRoleIndex);
  if (!queues) { queues = new WeakMap(); indexes.set(policyRoleIndex, queues); }
  let state = queues.get(queue);
  if (!state) {
    state = { latestDeleteByMemberId: new Map(), roleStatesByMemberId: new Map(), subscribed: false };
    queues.set(queue, state);
  }
  return state;
}

function nextMutationId(kind) {
  mutationSequence += 1;
  return kind + "-" + Date.now().toString(36) + "-" + mutationSequence;
}

export function createWorkspaceMemberActions(options = {}) {
  const { vault, policyRoleIndex, queue, isOffline = () => false } = options;
  if (!vault || !policyRoleIndex || !queue) throw new Error("createWorkspaceMemberActions 需要 vault、policyRoleIndex 与 queue");
  const actionState = actionStateFor(vault, policyRoleIndex, queue);
  const { latestDeleteByMemberId, roleStatesByMemberId } = actionState;

  function roleStateFor(mutation, confirmedSeq = null) {
    const memberId = mutation.memberIds[0];
    const generation = vault.memberGenerationOf(memberId);
    const sameGeneration = mutation.memberGeneration === undefined || mutation.memberGeneration === generation;
    if (!vault.hasMember(memberId)) return null;
    if (!sameGeneration) {
      const startSeq = vault.memberGenerationStartSeqOf(memberId);
      // 旧周期的失败/无序号回包不可影响新成员；不早于重新加入的明确成功仍是服务器事实。
      if (confirmedSeq === null || startSeq === null || confirmedSeq < startSeq) return null;
    }
    let state = roleStatesByMemberId.get(memberId);
    if (!state || state.generation !== generation) {
      state = { generation, baseRole: sameGeneration ? mutation.previousRole ?? null : policyRoleIndex.getRole(memberId), confirmedSeq: null, operations: new Map() };
      roleStatesByMemberId.set(memberId, state);
    }
    return state;
  }

  function renderRoleState(memberId, state) {
    let roleId = state.baseRole;
    for (const operation of state.operations.values()) {
      if (operation.optimistic) roleId = operation.mutation.payload.roleId;
    }
    if (roleId === null) policyRoleIndex.removeRole(memberId);
    else policyRoleIndex.setRole(memberId, roleId);
  }

  function settleRoleMutation(event) {
    if (event.type !== "mutation.succeeded" && event.type !== "mutation.failed") return;
    const mutation = event.mutation;
    const memberId = mutation.memberIds[0];
    if (!vault.hasMember(memberId)) {
      policyRoleIndex.removeMember(memberId);
      roleStatesByMemberId.delete(memberId);
      return;
    }
    const resultSeq = event.result?.appliedSeq;
    const seq = Number.isInteger(resultSeq) && resultSeq >= 0 ? resultSeq : null;
    const state = roleStateFor(mutation, event.type === "mutation.succeeded" ? seq : null);
    if (!state) return;
    let operation = state.operations.get(mutation.id);
    if (!operation) {
      operation = { mutation, optimistic: false };
      state.operations.set(mutation.id, operation);
    }
    if (event.type === "mutation.succeeded") {
      state.operations.delete(mutation.id);
      if (seq === null || state.confirmedSeq === null || seq >= state.confirmedSeq) {
        state.baseRole = mutation.payload.roleId;
        if (Number.isInteger(seq)) {
          state.confirmedSeq = seq;
          // 已确认的成员角色变更也构成版本屏障，旧快照缺项不能撤销它。
          vault.recordMutationSeq(memberId, seq);
        }
      }
    } else {
      // 失败操作仍供队列重试，但其乐观层不再参与当前角色计算。
      operation.optimistic = false;
    }
    renderRoleState(memberId, state);
    if (state.operations.size === 0) roleStatesByMemberId.delete(memberId);
  }

  const handleQueueEvent = (event) => {
    const mutation = event.mutation;
    if (!mutation) return;
    if (mutation.kind === "deleteWorkspaceMember") {
      vault.batchUpdates(() => {
        if (event.type === "mutation.succeeded") {
          for (const memberId of mutation.memberIds) {
            const seq = event.result.appliedSeq;
            const generation = mutation.memberGenerations?.[memberId];
            const sameGeneration = generation === undefined || generation === vault.memberGenerationOf(memberId);
            const stale = Number.isInteger(seq) ? seq < vault.lastMutationSeqOf(memberId) : !sameGeneration && vault.hasMember(memberId);
            if (!stale) finalizeMemberDeletion({ vault, policyRoleIndex, memberId, mutationSeq: seq });
            const latestDelete = latestDeleteByMemberId.get(memberId);
            if (stale && sameGeneration && (!latestDelete || latestDelete === mutation.id)) {
              vault.setPendingAction(memberId, null);
              vault.setLastError(memberId, null);
            }
          }
          return;
        }
        if (event.type !== "mutation.failed") return;
        for (const snapshot of mutation.rollbackMembers ?? []) {
          const current = vault.getMember(snapshot.id);
          const latestDelete = latestDeleteByMemberId.get(snapshot.id);
          const generation = mutation.memberGenerations?.[snapshot.id];
          if (!current || vault.isMemberDeleted(snapshot.id) || (latestDelete && latestDelete !== mutation.id)) continue;
          if (generation !== undefined && generation !== vault.memberGenerationOf(snapshot.id)) continue;
          // 回滚不覆盖在途刷新、较新操作或另一条链路已确认的删除。
          vault.restoreMember({ ...snapshot, ...current });
          vault.setLastError(snapshot.id, event.error?.message || "删除失败");
        }
      });
      return;
    }
    if (mutation.kind === "assignWorkspaceMemberRole") settleRoleMutation(event);
  };
  if (!actionState.subscribed) {
    queue.subscribe(handleQueueEvent);
    actionState.subscribed = true;
  }

  async function flushPendingMutations() {
    if (isOffline()) return null;
    try {
      return await queue.flush();
    } catch (error) {
      return { appliedSeq: null, succeeded: [], failed: [], ...error?.report, error };
    }
  }

  async function deleteMembers(memberIds) {
    const candidates = Array.isArray(memberIds) ? memberIds : [memberIds];
    const ids = [...new Set(candidates)].filter((id) => typeof id === "string" && vault.hasMember(id));
    if (ids.length === 0) return { queued: [], flushed: false, error: null };
    const rollbackMembers = ids.map((id) => vault.getMember(id)).filter(Boolean);
    const mutation = {
      id: nextMutationId("delete-members"),
      kind: "deleteWorkspaceMember",
      memberIds: ids,
      memberGenerations: Object.fromEntries(ids.map((id) => [id, vault.memberGenerationOf(id)])),
      rollbackMembers,
      successData: [{ code: "MEMBER_NOT_FOUND", behavior: "treatAsApplied" }],
      createdAt: Date.now(),
    };
    // 入队成功后才应用乐观状态；通知中重入的意图排在本操作之后。
    queue.enqueue(mutation);
    for (const id of ids) latestDeleteByMemberId.set(id, mutation.id);
    vault.batchUpdates(() => {
      for (const id of ids) vault.setPendingAction(id, "delete");
    });
    const report = await flushPendingMutations();
    return { queued: ids, flushed: report !== null, error: report?.error ?? null };
  }

  async function assignRole(memberId, roleId) {
    if (!vault.hasMember(memberId)) throw new PolicyRoleIndexError("ROLE_INDEX_UNKNOWN_MEMBER", "成员不存在，不能分配角色：" + memberId);
    if (!WORKSPACE_ROLE_IDS.includes(roleId)) throw new PolicyRoleIndexError("ROLE_INDEX_ROLE_INVALID", "未知工作区角色：" + roleId);
    const mutation = {
      id: nextMutationId("assign-role"),
      kind: "assignWorkspaceMemberRole",
      memberIds: [memberId],
      memberGeneration: vault.memberGenerationOf(memberId),
      payload: { roleId },
      previousRole: policyRoleIndex.getRole(memberId),
      createdAt: Date.now(),
    };
    queue.enqueue(mutation);
    const state = roleStateFor(mutation);
    state.operations.set(mutation.id, { mutation, optimistic: true });
    renderRoleState(memberId, state);
    const report = await flushPendingMutations();
    return { queued: [memberId], flushed: report !== null, error: report?.error ?? null };
  }

  return { deleteMembers, assignRole, flushPendingMutations };
}

export function createWorkspaceRuntime(options = {}) {
  const vault = options.vault ?? new MemberVault(options.members ?? []);
  const policyRoleIndex = options.policyRoleIndex ?? new PolicyRoleIndex(options.policy ?? {});
  const queue = options.queue ?? new OfflineMutationQueue({ transport: options.transport, batchSize: options.batchSize });
  const isOffline = typeof options.isOffline === "function" ? options.isOffline : () => false;
  const actions = createWorkspaceMemberActions({ vault, policyRoleIndex, queue, isOffline });
  const stream = options.stream ?? new DeltaStream({ vault, policyRoleIndex });
  return { vault, policyRoleIndex, queue, stream, actions, deleteMembers: actions.deleteMembers, assignRole: actions.assignRole, flushPendingMutations: actions.flushPendingMutations };
}

export const WORKSPACE_ROLE_IDS = Object.freeze(["owner", "admin", "approver", "manager", "member"]);

export class PolicyRoleIndexError extends Error {
  constructor(code, message) {
    super(message);
    this.name = "PolicyRoleIndexError";
    this.code = code;
  }
}

export class PolicyRoleIndex {
  #roleByMemberId = new Map();
  #delegateByMemberId = new Map();

  constructor(options = {}) {
    for (const [memberId, roleId] of Object.entries(options.roleByMemberId ?? {})) this.setRole(memberId, roleId);
    for (const [memberId, delegateId] of Object.entries(options.delegateByMemberId ?? {})) this.delegateApproval(memberId, delegateId);
  }

  getRole(memberId) { return this.#roleByMemberId.get(memberId) ?? null; }

  hasRole(memberId) { return this.#roleByMemberId.has(memberId); }

  listRoles() {
    return [...this.#roleByMemberId.entries()].map(([memberId, roleId]) => ({ memberId, roleId })).sort((left, right) => left.memberId.localeCompare(right.memberId));
  }

  setRole(memberId, roleId) {
    if (typeof memberId !== "string" || memberId.length === 0) throw new PolicyRoleIndexError("ROLE_INDEX_MEMBER_INVALID", "成员 id 必须是非空字符串");
    if (!WORKSPACE_ROLE_IDS.includes(roleId)) throw new PolicyRoleIndexError("ROLE_INDEX_ROLE_INVALID", "未知工作区角色：" + roleId);
    this.#roleByMemberId.set(memberId, roleId);
    return roleId;
  }

  removeRole(memberId) { return this.#roleByMemberId.delete(memberId); }

  removeMember(memberId) {
    const successor = this.#delegateByMemberId.get(memberId);
    const incoming = [...this.#delegateByMemberId.entries()].filter(([, delegateId]) => delegateId === memberId);
    const removedRole = this.#roleByMemberId.delete(memberId);
    const removedDelegation = this.#delegateByMemberId.delete(memberId);
    // 先解除所有入边，检查重接时才不会把即将清理的边误当作有效后继。
    for (const [sourceId] of incoming) this.#delegateByMemberId.delete(sourceId);
    for (const [sourceId] of incoming) {
      if (this.#roleByMemberId.has(sourceId) && this.#canReconnectDelegation(sourceId, successor)) {
        this.#delegateByMemberId.set(sourceId, successor);
      }
    }
    return removedRole || removedDelegation || incoming.length > 0;
  }

  #canReconnectDelegation(memberId, successor) {
    const visited = new Set([memberId]);
    let cursor = successor;
    while (typeof cursor === "string") {
      if (!this.#roleByMemberId.has(cursor) || visited.has(cursor)) return false;
      visited.add(cursor);
      if (!this.#delegateByMemberId.has(cursor)) return true;
      cursor = this.#delegateByMemberId.get(cursor);
    }
    return false;
  }

  getDelegate(memberId) { return this.#delegateByMemberId.get(memberId) ?? null; }

  listDelegations() {
    return [...this.#delegateByMemberId.entries()].map(([memberId, delegateId]) => ({ memberId, delegateId })).sort((left, right) => left.memberId.localeCompare(right.memberId));
  }

  delegateApproval(memberId, delegateId) {
    if (!this.#roleByMemberId.has(memberId)) throw new PolicyRoleIndexError("ROLE_INDEX_UNKNOWN_MEMBER", "转交发起人不在角色索引中：" + memberId);
    if (!this.#roleByMemberId.has(delegateId)) throw new PolicyRoleIndexError("ROLE_INDEX_UNKNOWN_MEMBER", "转交目标不在角色索引中：" + delegateId);
    if (memberId === delegateId) throw new PolicyRoleIndexError("ROLE_INDEX_SELF_DELEGATION", "审批不能转交给自己");
    this.#delegateByMemberId.set(memberId, delegateId);
    return delegateId;
  }

  removeDelegation(memberId) { return this.#delegateByMemberId.delete(memberId); }

  resolveApproverId(memberId) {
    if (!this.#roleByMemberId.has(memberId)) throw new PolicyRoleIndexError("ROLE_INDEX_UNKNOWN_MEMBER", "成员不在角色索引中：" + memberId);
    const visited = [];
    let cursor = memberId;
    while (this.#delegateByMemberId.has(cursor)) {
      if (visited.includes(cursor)) throw new PolicyRoleIndexError("ROLE_INDEX_DELEGATION_CYCLE", "审批转交链存在环路：" + [...visited, cursor].join(" -> "));
      visited.push(cursor);
      const next = this.#delegateByMemberId.get(cursor);
      if (!this.#roleByMemberId.has(next)) throw new PolicyRoleIndexError("ROLE_INDEX_DANGLING_DELEGATE", "审批转交目标不存在：" + next);
      cursor = next;
    }
    return cursor;
  }
}

export class OfflineMutationQueueError extends Error {
  constructor(code, message, options = {}) {
    super(message, options);
    this.name = "OfflineMutationQueueError";
    this.code = code;
  }
}

const DEFAULT_BATCH_SIZE = 20;

export class OfflineMutationQueue {
  #transport;
  #batchSize;
  #pending = [];
  #inflight = null;
  #inflightIds = new Set();
  #listeners = new Set();

  constructor(options = {}) {
    if (!options.transport || typeof options.transport.send !== "function") throw new OfflineMutationQueueError("QUEUE_TRANSPORT_REQUIRED", "离线队列需要提供 transport.send");
    this.#transport = options.transport;
    this.#batchSize = Number.isInteger(options.batchSize) && options.batchSize > 0 ? options.batchSize : DEFAULT_BATCH_SIZE;
  }

  get size() { return this.#pending.length; }
  get isFlushing() { return this.#inflight !== null; }

  listPending() {
    return this.#pending.map((mutation) => ({ id: mutation.id, kind: mutation.kind, memberIds: [...(mutation.memberIds ?? [])], createdAt: mutation.createdAt ?? null }));
  }

  enqueue(mutation) {
    if (!mutation || typeof mutation.id !== "string" || mutation.id.length === 0) throw new OfflineMutationQueueError("QUEUE_MUTATION_INVALID", "待决操作必须包含非空 id");
    if (typeof mutation.kind !== "string" || mutation.kind.length === 0) throw new OfflineMutationQueueError("QUEUE_MUTATION_INVALID", "待决操作必须包含非空 kind");
    if (this.#inflightIds.has(mutation.id) || this.#pending.some((item) => item.id === mutation.id)) throw new OfflineMutationQueueError("QUEUE_DUPLICATE_MUTATION", "待决操作 id 重复：" + mutation.id);
    this.#pending.push(mutation);
    return mutation.id;
  }

  subscribe(listener) {
    this.#listeners.add(listener);
    return () => this.#listeners.delete(listener);
  }

  flush() {
    if (this.#inflight) return this.#inflight;
    if (this.#pending.length === 0) return Promise.resolve({ appliedSeq: null, succeeded: [], failed: [] });
    const batch = this.#pending.slice(0, this.#batchSize);
    this.#pending = this.#pending.slice(batch.length);
    this.#inflightIds = new Set(batch.map((mutation) => mutation.id));
    // 先建立单飞承诺，再调用 transport，避免同步回调重入 flush 时重复发送。
    let start;
    const completion = new Promise((resolve, reject) => {
      start = () => this.#sendBatch(batch).then(resolve, reject);
    });
    this.#inflight = completion.finally(() => {
      this.#inflight = null;
      this.#inflightIds.clear();
    });
    const inflight = this.#inflight;
    start();
    return inflight;
  }

  async #sendBatch(batch) {
    let result;
    try {
      result = await this.#transport.send(batch);
    } catch (cause) {
      const error = new OfflineMutationQueueError("QUEUE_BATCH_FAILED", "批量同步失败：" + (cause && cause.message ? cause.message : "未知错误"), { cause });
      this.#failBatch(batch, error);
      throw error;
    }
    try {
      return this.#settleBatch(batch, result);
    } catch (cause) {
      const error = cause instanceof OfflineMutationQueueError ? cause : new OfflineMutationQueueError("QUEUE_RESULT_INVALID", "批量同步结果无法解析", { cause });
      this.#failBatch(batch, error);
      throw error;
    }
  }

  #settleBatch(batch, result) {
    if (!result || typeof result !== "object" || Array.isArray(result)) throw new OfflineMutationQueueError("QUEUE_RESULT_INVALID", "transport.send 必须返回对象");
    const appliedIds = new Set(Array.isArray(result.applied) ? result.applied : []);
    const appliedSeq = this.#validSeq(result.appliedSeq);
    const idempotentById = this.#entriesByMutationId(result.idempotent);
    const failedById = this.#entriesByMutationId(result.failed);
    const succeeded = [];
    const failed = [];
    const events = [];
    for (const mutation of batch) {
      if (appliedIds.has(mutation.id)) {
        const outcome = { mutation, result: { appliedSeq, code: null, outcome: "applied" } };
        succeeded.push(outcome);
        events.push({ type: "mutation.succeeded", ...outcome });
        continue;
      }
      const entry = idempotentById.get(mutation.id) ?? failedById.get(mutation.id);
      // 同一个声明也适用于 failed 中的幂等错误，不能因传输分组不同而回滚。
      if (entry && this.#declaresIdempotentSuccess(mutation, entry.code)) {
        const outcome = { mutation, result: { appliedSeq: this.#validSeq(entry.appliedSeq) ?? appliedSeq, code: entry.code, outcome: "idempotent" } };
        succeeded.push(outcome);
        events.push({ type: "mutation.succeeded", ...outcome });
        continue;
      }
      const error = entry ? { code: entry.code, message: entry.message ?? "" } : { code: "QUEUE_RESULT_MISSING", message: "服务器结果缺少该待决操作" };
      const outcome = { mutation, error };
      failed.push(outcome);
      events.push({ type: "mutation.failed", ...outcome });
    }
    // 先通知失败回滚，再重排；通知期间入队的操作也属于必须保留的队尾。
    for (const event of events) this.#emit(event);
    this.#prependForRetry(failed.map((outcome) => outcome.mutation));
    return { appliedSeq, succeeded, failed };
  }

  #validSeq(seq) { return Number.isInteger(seq) && seq >= 0 ? seq : null; }

  #entriesByMutationId(entries) {
    return new Map((Array.isArray(entries) ? entries : [])
      .filter((entry) => entry && typeof entry.mutationId === "string")
      .map((entry) => [entry.mutationId, entry]));
  }

  #prependForRetry(mutations) {
    this.#pending = [...mutations, ...this.#pending];
  }

  #failBatch(batch, error) {
    const failed = batch.map((mutation) => ({ mutation, error: { code: error.code, message: error.message } }));
    error.report = { appliedSeq: null, succeeded: [], failed };
    for (const outcome of failed) this.#emit({ type: "mutation.failed", ...outcome });
    this.#prependForRetry(batch);
  }

  #declaresIdempotentSuccess(mutation, code) {
    return Array.isArray(mutation.successData) && mutation.successData.some((entry) => entry && entry.code === code && entry.behavior === "treatAsApplied");
  }

  #emit(payload) {
    for (const listener of [...this.#listeners]) {
      try { listener(payload); } catch {}
    }
  }
}

export function createOfflineMutationQueue(options) { return new OfflineMutationQueue(options); }

// 成员动作、服务器删除事件与快照确认删除共用此入口。
export function finalizeMemberDeletion({ vault, policyRoleIndex = null, memberId, mutationSeq = null }) {
  if (Number.isInteger(mutationSeq)) {
    const previousSeq = vault.lastMutationSeqOf(memberId);
    vault.recordMutationSeq(memberId, mutationSeq);
    if (mutationSeq < previousSeq) return false;
  }
  // 删除通知发出前，版本屏障、角色及审批路由必须已就绪。
  if (policyRoleIndex) policyRoleIndex.removeMember(memberId);
  return vault.removeMember(memberId, { mutationSeq });
}

const MEMBER_STATUSES = new Set(["active", "invited", "suspended"]);

export class MemberVaultError extends Error {
  constructor(code, message) {
    super(message);
    this.name = "MemberVaultError";
    this.code = code;
  }
}

export function normalizeMember(input) {
  if (!input || typeof input !== "object") throw new MemberVaultError("MEMBER_INVALID", "成员记录必须是对象");
  if (typeof input.id !== "string" || input.id.trim().length === 0) throw new MemberVaultError("MEMBER_ID_INVALID", "成员 id 必须是非空字符串");
  const status = input.status ?? "active";
  if (!MEMBER_STATUSES.has(status)) throw new MemberVaultError("MEMBER_STATUS_INVALID", "未知成员状态：" + status);
  return {
    id: input.id,
    email: typeof input.email === "string" ? input.email : "",
    displayName: typeof input.displayName === "string" && input.displayName.length > 0 ? input.displayName : (typeof input.email === "string" ? input.email : input.id),
    status,
    pendingAction: input.pendingAction ?? null,
    lastError: input.lastError ?? null,
  };
}

export class MemberVault {
  #members = new Map();
  #mutationSeq = new Map();
  // 删除记录独立于成员数据；null 表示确认删除但尚无可比较的服务端序号。
  #deletionSeq = new Map();
  #generationByMemberId = new Map();
  #generationStartSeqByMemberId = new Map();
  #revision = 0;
  #listeners = new Set();
  #batchDepth = 0;
  #events = [];
  #notifying = false;

  constructor(members = []) {
    for (const member of members) {
      const normalized = normalizeMember(member);
      this.#members.set(normalized.id, normalized);
    }
  }

  get revision() { return this.#revision; }

  listMembers() {
    return [...this.#members.values()].map((member) => ({ ...member })).sort((left, right) => left.id.localeCompare(right.id));
  }

  getMember(id) {
    const member = this.#members.get(id);
    return member ? { ...member } : null;
  }

  hasMember(id) { return this.#members.has(id); }

  memberGenerationOf(id) { return this.#generationByMemberId.get(id) ?? 0; }

  memberGenerationStartSeqOf(id) { return this.#generationStartSeqByMemberId.get(id) ?? null; }

  batchUpdates(update) {
    if (typeof update !== "function") throw new MemberVaultError("MEMBER_BATCH_INVALID", "批量更新需要同步回调函数");
    this.#batchDepth += 1;
    try { return update(); }
    finally {
      this.#batchDepth -= 1;
      this.#drainEvents();
    }
  }

  isMemberDeleted(id) { return this.#deletionSeq.has(id); }

  listDeletedMemberIds() { return [...this.#deletionSeq.keys()]; }

  canApplyMember(id, seq) {
    if (!Number.isInteger(seq) || seq < 0) throw new MemberVaultError("MEMBER_SEQ_INVALID", "变更序号必须是非负整数");
    const lastSeq = this.lastMutationSeqOf(id);
    if (seq < lastSeq) return false;
    if (!this.#deletionSeq.has(id)) return true;
    // 同序号的成员数据不能覆盖删除；有序号且严格更新的数据才可重新加入。
    return this.#deletionSeq.get(id) !== null && seq > lastSeq;
  }

  upsertMember(input, options = {}) {
    const normalized = normalizeMember(input);
    if (options.mutationSeq !== undefined && options.mutationSeq !== null) this.recordMutationSeq(normalized.id, options.mutationSeq);
    const current = this.#members.get(normalized.id);
    if (!current) this.#generationStartSeqByMemberId.set(normalized.id, options.mutationSeq ?? null);
    if (current && normalized.pendingAction === null) normalized.pendingAction = current.pendingAction;
    this.#members.set(normalized.id, normalized);
    this.#deletionSeq.delete(normalized.id);
    this.#bump("member.upserted", normalized.id);
    return { ...normalized };
  }

  setPendingAction(id, action) {
    const current = this.#members.get(id);
    if (!current) return false;
    this.#members.set(id, { ...current, pendingAction: action ?? null });
    this.#bump("member.pending-changed", id);
    return true;
  }

  setLastError(id, lastError) {
    const current = this.#members.get(id);
    if (!current) return false;
    this.#members.set(id, { ...current, lastError: lastError ?? null });
    this.#bump("member.error-changed", id);
    return true;
  }

  removeMember(id, options = {}) {
    const wasDeleted = this.#deletionSeq.has(id);
    const seq = options.mutationSeq;
    if (Number.isInteger(seq)) {
      if (seq < 0) throw new MemberVaultError("MEMBER_SEQ_INVALID", "变更序号必须是非负整数");
      if (seq < this.lastMutationSeqOf(id)) return false;
      this.recordMutationSeq(id, seq);
      this.#deletionSeq.set(id, seq);
    } else if (!this.#deletionSeq.has(id)) {
      this.#deletionSeq.set(id, null);
    }
    // 同一 id 重新加入后，上一成员周期的失败不能恢复旧角色或旧反馈。
    if (!wasDeleted) {
      this.#generationByMemberId.set(id, this.memberGenerationOf(id) + 1);
      this.#generationStartSeqByMemberId.delete(id);
    }
    const removed = this.#members.delete(id);
    if (removed) this.#bump("member.removed", id);
    return removed;
  }

  restoreMember(input) {
    const normalized = normalizeMember({ ...input, pendingAction: null, lastError: null });
    if (!this.#members.has(normalized.id)) this.#generationStartSeqByMemberId.set(normalized.id, null);
    this.#members.set(normalized.id, normalized);
    this.#deletionSeq.delete(normalized.id);
    this.#bump("member.restored", normalized.id);
    return { ...normalized };
  }

  replaceMembers(members, options = {}) {
    const seq = options.generationStartSeq ?? null;
    if (seq !== null && (!Number.isInteger(seq) || seq < 0)) throw new MemberVaultError("MEMBER_SEQ_INVALID", "变更序号必须是非负整数");
    const next = new Map();
    for (const member of members ?? []) {
      const normalized = normalizeMember(member);
      next.set(normalized.id, normalized);
    }
    for (const id of this.#members.keys()) {
      if (!next.has(id)) {
        this.#generationByMemberId.set(id, this.memberGenerationOf(id) + 1);
        this.#generationStartSeqByMemberId.delete(id);
      }
    }
    for (const id of next.keys()) {
      if (!this.#members.has(id)) this.#generationStartSeqByMemberId.set(id, seq);
    }
    this.#members = next;
    for (const id of next.keys()) this.#deletionSeq.delete(id);
    this.#bump("members.replaced", null);
  }

  recordMutationSeq(id, seq) {
    if (!Number.isInteger(seq) || seq < 0) throw new MemberVaultError("MEMBER_SEQ_INVALID", "变更序号必须是非负整数");
    const current = this.#mutationSeq.get(id) ?? 0;
    if (!this.#mutationSeq.has(id) || seq > current) this.#mutationSeq.set(id, seq);
    return this.#mutationSeq.get(id);
  }

  lastMutationSeqOf(id) { return this.#mutationSeq.get(id) ?? 0; }

  subscribe(listener) {
    this.#listeners.add(listener);
    return () => this.#listeners.delete(listener);
  }

  #bump(reason, memberId) {
    this.#revision += 1;
    this.#events.push({ reason, memberId, revision: this.#revision });
    this.#drainEvents();
  }

  #drainEvents() {
    if (this.#batchDepth > 0 || this.#notifying) return;
    this.#notifying = true;
    try {
      while (this.#events.length > 0) {
        const event = this.#events.shift();
        for (const listener of [...this.#listeners]) {
          try { listener(event); } catch {}
        }
      }
    } finally {
      this.#notifying = false;
    }
  }
}

import { normalizeMember } from "../store/MemberVault.js";
import { finalizeMemberDeletion } from "../store/finalizeMemberDeletion.js";

export class DeltaStreamError extends Error {
  constructor(code, message) {
    super(message);
    this.name = "DeltaStreamError";
    this.code = code;
  }
}

const CONNECTION_STATES = new Set(["online", "offline"]);

export class DeltaStream {
  #vault;
  #policyRoleIndex;
  #cursor = 0;
  #connectionState = "online";
  #listeners = new Set();

  constructor(options = {}) {
    if (!options.vault) throw new DeltaStreamError("DELTA_VAULT_REQUIRED", "DeltaStream 需要 MemberVault 实例");
    this.#vault = options.vault;
    this.#policyRoleIndex = options.policyRoleIndex ?? null;
  }

  get cursor() { return this.#cursor; }
  get connectionState() { return this.#connectionState; }
  isOffline() { return this.#connectionState === "offline"; }

  setConnectionState(state) {
    if (!CONNECTION_STATES.has(state)) throw new DeltaStreamError("DELTA_CONNECTION_INVALID", "未知连接状态：" + state);
    const changed = this.#connectionState !== state;
    this.#connectionState = state;
    if (changed) this.#emit({ type: "connection.changed", state });
    return state;
  }

  subscribe(listener) {
    this.#listeners.add(listener);
    return () => this.#listeners.delete(listener);
  }

  applyDelta(delta) {
    if (!delta || !Number.isInteger(delta.seq) || delta.seq < 0 || !Array.isArray(delta.events)) throw new DeltaStreamError("DELTA_INVALID", "增量消息必须包含非负整数 seq 与 events 数组");
    const seq = delta.seq;
    if (seq <= this.#cursor) return { applied: false, seq: this.#cursor };
    const events = Array.from(delta.events, (event) => this.#normalizeEvent(event));
    this.#vault.batchUpdates(() => {
      for (const event of events) this.#applyEvent(event, seq);
      // 先完成全部写入及游标，再发成员通知，观察者重入不能回退外层状态。
      this.#cursor = Math.max(this.#cursor, seq);
    });
    this.#emit({ type: "delta.applied", seq });
    return { applied: true, seq };
  }

  applyServerSnapshot(snapshot) {
    if (!snapshot || !Number.isInteger(snapshot.snapshotSeq) || snapshot.snapshotSeq < 0 || !Array.isArray(snapshot.members)) throw new DeltaStreamError("SNAPSHOT_INVALID", "快照必须包含非负整数 snapshotSeq 与 members 数组");
    // 先完整校验，再修改存储，避免无效成员造成半份快照落库。
    const members = Array.from(snapshot.members, (member) => normalizeMember(member));
    const seq = snapshot.snapshotSeq;
    this.#vault.batchUpdates(() => {
      const current = new Map(this.#vault.listMembers().map((member) => [member.id, member]));
      const snapshotIds = new Set(members.map((member) => member.id));
      const next = new Map();
      const acceptedIds = new Set();
      for (const member of members) {
        const local = current.get(member.id);
        if (!this.#vault.canApplyMember(member.id, seq)) {
          if (local) next.set(local.id, local);
          continue;
        }
        if (local && local.pendingAction !== null) {
          member.pendingAction = local.pendingAction;
          member.lastError = local.lastError;
        }
        next.set(member.id, member);
        acceptedIds.add(member.id);
      }
      const removedIds = [];
      for (const local of current.values()) {
        if (snapshotIds.has(local.id)) continue;
        // 旧快照的缺项也不能删除更新的成员；未结算的本地操作仍保留其乐观状态。
        if (seq < this.#vault.lastMutationSeqOf(local.id) || local.pendingAction !== null) next.set(local.id, local);
        else removedIds.push(local.id);
      }
      for (const id of acceptedIds) this.#vault.recordMutationSeq(id, seq);
      for (const id of this.#vault.listDeletedMemberIds()) {
        // 新快照继续确认缺席时推进版本屏障，但不凭缺项猜测无序号删除的真实时刻。
        if (!snapshotIds.has(id)) this.#vault.recordMutationSeq(id, seq);
      }
      for (const memberId of removedIds) {
        finalizeMemberDeletion({ vault: this.#vault, policyRoleIndex: this.#policyRoleIndex, memberId, mutationSeq: seq });
      }
      this.#vault.replaceMembers([...next.values()], { generationStartSeq: seq });
      this.#cursor = Math.max(this.#cursor, seq);
    });
    this.#emit({ type: "snapshot.applied", seq });
    return { applied: true, snapshotSeq: seq };
  }

  #normalizeEvent(event) {
    if (!event || typeof event.type !== "string") throw new DeltaStreamError("DELTA_EVENT_INVALID", "增量事件缺少 type");
    if (event.type === "member.added" || event.type === "member.updated") {
      if (!event.member || typeof event.member.id !== "string") throw new DeltaStreamError("DELTA_EVENT_INVALID", "成员事件缺少 member.id");
      return { type: event.type, member: normalizeMember(event.member) };
    }
    if (event.type === "member.removed") {
      if (typeof event.memberId !== "string" || event.memberId.trim().length === 0) throw new DeltaStreamError("DELTA_EVENT_INVALID", "移除事件缺少有效 memberId");
      return { type: event.type, memberId: event.memberId };
    }
    throw new DeltaStreamError("DELTA_EVENT_UNKNOWN", "未知增量事件：" + event.type);
  }

  #applyEvent(event, seq) {
    if (event.type === "member.added" || event.type === "member.updated") {
      if (!this.#vault.canApplyMember(event.member.id, seq)) return;
      this.#vault.upsertMember(event.member, { mutationSeq: seq });
      return;
    }
    finalizeMemberDeletion({ vault: this.#vault, policyRoleIndex: this.#policyRoleIndex, memberId: event.memberId, mutationSeq: seq });
  }

  #emit(payload) {
    for (const listener of [...this.#listeners]) {
      try { listener(payload); } catch {}
    }
  }
}

export function isMemberHidden(options = {}) {
  return !options.isOffline && (options.pendingAction ?? null) === "delete";
}

export function buildMemberRowViewModel(options = {}) {
  const member = options.member;
  if (!member) return null;
  const pendingAction = member.pendingAction ?? null;
  const isOffline = Boolean(options.isOffline);
  const hidden = isMemberHidden({ isOffline, pendingAction });
  return {
    id: member.id,
    displayName: typeof member.displayName === "string" && member.displayName.length > 0 ? member.displayName : (member.email ?? member.id),
    email: member.email ?? "",
    status: member.status ?? "active",
    pendingAction,
    hidden,
    interactive: !hidden,
    offlineIndicator: isOffline && pendingAction !== null,
    errorText: member.lastError ?? null,
  };
}

export function buildMemberListViewModel(options = {}) {
  const rows = (options.members ?? []).map((member) => buildMemberRowViewModel({ member, isOffline: options.isOffline })).filter(Boolean);
  return {
    rows,
    visibleRows: rows.filter((row) => !row.hidden),
    hiddenCount: rows.filter((row) => row.hidden).length,
  };
}
